const std = @import("std");

const AgeError = error{ Negative, TooOld };

fn checkAge(age: i32) AgeError!i32 {
    if (age < 0) return AgeError.Negative;
    if (age > 150) return AgeError.TooOld;
    return age;
}

pub fn main() void {
    const a = checkAge(30) catch 0;
    const b = checkAge(-5) catch 0;
    std.debug.print("{d} {d}\n", .{ a, b });
}

