        std.debug.print("Failed: {}\n", .{err});
        return;
    };
    std.debug.print("{d}\n", .{x});
}

const std = @import("std");

fn half(n: u32) !u32 {
    if (n % 2 != 0) return error.Odd;
    return n / 2;
}

fn quarter(n: u32) !u32 {
    const h = try half(n);
    return try half(h);
}

pub fn main() !void {
    std.debug.print("{d}\n", .{try quarter(20)});
    const q = quarter(10) catch 99;
    std.debug.print("{d}\n", .{q});
}

